package com.pirris.mapper;

import java.util.List;

import org.mapstruct.BeanMapping;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingConstants;
import org.mapstruct.MappingTarget;
import org.mapstruct.NullValuePropertyMappingStrategy;

import com.pirris.dto.ClientDraftDto;
import com.pirris.dto.client.ClientDetailDto;
import com.pirris.dto.client.ClientSummaryDto;
import com.pirris.model.ClientModel;

/**
 * Compile-time mapper between {@link ClientModel} and the Clienti view DTOs.
 * Generated by MapStruct as a CDI bean (see {@code -Amapstruct.defaultComponentModel=cdi}).
 *
 * <p>The derived fields {@code balanceCents} and {@code history} are not present
 * on the entity: they come from the accounting logic (Phase 3,
 * {@code AccountService}). The mapper fills them with neutral values
 * (zero balance, empty history); the service overrides them once that logic
 * exists.</p>
 */
@Mapper(componentModel = MappingConstants.ComponentModel.CDI)
public interface ClientMapper {

    // ---- entity -> DTO (reads) ----

    @Mapping(target = "balanceCents", constant = "0L")
    ClientSummaryDto toSummary(ClientModel client);

    List<ClientSummaryDto> toSummaries(List<ClientModel> clients);

    @Mapping(target = "balanceCents", constant = "0L")
    @Mapping(target = "history", expression = "java(java.util.List.of())")
    ClientDetailDto toDetail(ClientModel client);

    // ---- draft -> entity (writes) ----

    /**
     * Applies the editable fields of a draft onto an existing client. Scheduling
     * preferences, identity and audit columns, {@code joinedOn} and the archived
     * flag are left untouched (owned elsewhere). Null string fields on the draft
     * are ignored, preserving the entity's non-null defaults.
     */
    @BeanMapping(nullValuePropertyMappingStrategy = NullValuePropertyMappingStrategy.IGNORE)
    @Mapping(target = "id", ignore = true)
    @Mapping(target = "studioId", ignore = true)
    @Mapping(target = "createdAt", ignore = true)
    @Mapping(target = "updatedAt", ignore = true)
    @Mapping(target = "joinedOn", ignore = true)
    @Mapping(target = "archived", ignore = true)
    @Mapping(target = "preferredServiceId", ignore = true)
    @Mapping(target = "preferredRateId", ignore = true)
    @Mapping(target = "preferredPackageId", ignore = true)
    @Mapping(target = "preferredTime", ignore = true)
    @Mapping(target = "preferredDurationMinutes", ignore = true)
    @Mapping(target = "preferredPriceCents", ignore = true)
    void applyDraft(@MappingTarget ClientModel client, ClientDraftDto draft);
}
